-- insert-sevilla-centers.sql
-- Inserta los 218 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Sevilla capital investigados y humanizados en este sprint.
-- Fuente primaria: "Centros de primer ciclo de educacion infantil en Andalucia, con
-- alumnado matriculado" (Junta de Andalucia, Consejeria de Desarrollo Educativo y
-- Formacion Profesional, portal de datos abiertos), filtrado por D_MUNICIPIO='Sevilla'.
-- Complementado con webs oficiales propias de un subconjunto de centros privados con
-- servicios confirmados. Ver docs/data-sources-sevilla.md y
-- data/enrichment/sevilla-centers.json.
--
-- Ambito: unicamente el termino municipal de Sevilla capital (D_MUNICIPIO='Sevilla' en
-- la fuente oficial). Se excluyen explicitamente municipios del area metropolitana
-- (Dos Hermanas, Mairena del Aljarafe, San Juan de Aznalfarache, Alcala de Guadaira,
-- Camas, Tomares, etc.) aunque aparecieran en la misma fuente provincial/autonomica.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid, Barcelona,
-- Valencia, Zaragoza y Murcia).
-- No toca ningun centro de Madrid, Barcelona, Valencia, Zaragoza ni Murcia. No borra ni
-- modifica filas existentes (upsert por slug: si un slug ya existe se actualiza, no se
-- duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "sevilla" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('sevilla', 'Sevilla', 'Sevilla', 'Andalucía')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
